"""Generate the React app's model defaults and offline fallback rows from the registry."""

from __future__ import annotations

import json
import os
from typing import Any

from tools.model_catalog.registry_text import ROOT

GENERATED_PATH = ROOT / "frontend-react" / "src" / "config" / "generated" / "registryDefaults.ts"

# Fields that change with the clock (promotion windows, peak/off-peak schedules) are
# left out so the generated file only changes when the registry changes.
_TIME_DEPENDENT = {
    "pricing_rule_id",
    "pricing_effective_from",
    "pricing_effective_until",
    "cached_input_cost_per_1m",
    "cache_write_cost_per_1m",
    "long_context_threshold_tokens",
}


def _latest_rule(model: dict[str, Any]) -> dict[str, Any] | None:
    rules = [
        rule
        for rule in model.get("pricing_rules") or []
        if str(rule.get("processing_mode") or "standard") == "standard"
    ]
    return max(
        rules,
        key=lambda rule: str(rule.get("effective_from") or "1970-01-01T00:00:00Z"),
        default=None,
    )


def _fallback_rows(registry: dict[str, Any], keys: list[str]) -> list[dict[str, Any]]:
    os.environ.setdefault("MODEL_PRICING_MODE", "legacy")
    from orchestrator.model_registry import ModelRegistry
    from server.routes.catalog import _model_to_dto

    runtime = ModelRegistry.from_yaml()
    raw = {
        (provider, str(model["name"])): model
        for provider, block in registry["providers"].items()
        for model in block.get("models") or []
    }
    rows = []
    selectable = {
        f"{candidate.provider}:{candidate.model_name}": candidate
        for candidate in runtime.list_selectable_models()
    }
    # Defaults determine the initial choices, never the complete menu inventory.
    # Keep their ordering, then include every current selectable registry model.
    for key in dict.fromkeys([*keys, *sorted(selectable)]):
        provider, _, name = key.partition(":")
        candidate = selectable.get(key)
        if candidate is None:
            raise ValueError(f"Default model {key} is not selectable in the registry")
        row = _model_to_dto(candidate).model_dump(exclude_none=True)
        for field in _TIME_DEPENDENT:
            row.pop(field, None)
        rule = _latest_rule(raw[(provider, name)])
        if rule is not None:
            row["input_cost_per_1m"] = float(rule["input"])
            row["output_cost_per_1m"] = float(rule["output"])
        rows.append(row)
    return rows


def render_frontend_defaults(registry: dict[str, Any]) -> str:
    ui = registry.get("ui_defaults") or {}
    ask = dict(ui.get("ask_by_plan") or {})
    compare = list(ui.get("compare") or [])
    added = str(ui.get("compare_added") or "")
    keys: list[str] = []
    for key in [*ask.values(), *compare, added]:
        if key and key not in keys:
            keys.append(key)
    rows = _fallback_rows(registry, keys)
    return (
        "// Generated by `python scripts/models.py sync-frontend` from config/model_registry.yaml.\n"
        "// Do not edit by hand; `python scripts/models.py check` fails when this file is stale.\n"
        'import type { ModelCatalogItem, SubscriptionPlanCode } from "../../types";\n\n'
        "export const DEFAULT_ASK_MODEL_KEYS_BY_PLAN: Record<SubscriptionPlanCode, string> = "
        f"{json.dumps(ask, indent=2)};\n\n"
        f"export const DEFAULT_COMPARE_MODEL_KEYS = {json.dumps(compare)} as const;\n\n"
        f"export const DEFAULT_ADDED_COMPARE_MODEL_KEY = {json.dumps(added)};\n\n"
        "/** Complete selectable registry, used while /v1/model-options loads or is unavailable. */\n"
        f"export const FALLBACK_MODELS: ModelCatalogItem[] = {json.dumps(rows, indent=2)};\n"
    )


def write_frontend_defaults(registry: dict[str, Any]) -> bool:
    text = render_frontend_defaults(registry)
    GENERATED_PATH.parent.mkdir(parents=True, exist_ok=True)
    if GENERATED_PATH.exists() and GENERATED_PATH.read_text(encoding="utf-8") == text:
        return False
    GENERATED_PATH.write_text(text, encoding="utf-8")
    return True
